package mz.bam.seeky.android;

import android.media.*;import java.io.*;import java.nio.*;import java.util.function.BooleanSupplier;

/** Pull decoder: prepare only the background samples required by the next voice chunk. */
final class BackgroundPcm implements AutoCloseable {
 interface Progress {void update(long decodedUs,long durationUs);}
 final File file,meta,directory;final BooleanSupplier cancel;final Progress progress;
 int rate,channels,encoding=AudioFormat.ENCODING_PCM_16BIT;long frames,durationUs,positionUs,lastOutput,lastProgress;
 boolean complete,inputDone,outputDone,closed;MediaExtractor extractor;MediaCodec codec;RandomAccessFile wave;
 WaveJoiner.Format waveFormat;FileOutputStream output;long waveLeft;
 BackgroundPcm(File input,File directory,BooleanSupplier cancel,Progress progress)throws Exception{
  this.directory=directory;this.cancel=cancel;this.progress=progress;file=new File(directory,"background.pcm");meta=new File(directory,"background.info");
  if(file.isFile()&&meta.isFile())try(DataInputStream in=new DataInputStream(new FileInputStream(meta))){rate=in.readInt();channels=in.readInt();frames=file.length()/Math.max(1,channels*2);if(frames>0&&rate>=8000&&rate<=192000&&channels>=1&&channels<=8&&file.length()%(channels*2)==0){complete=true;return;}}catch(IOException ignored){}
  meta.delete();rate=channels=0;frames=0;
  try{
   output=new FileOutputStream(file);try(RandomAccessFile probe=new RandomAccessFile(input,"r")){if(probe.length()>=4&&probe.readInt()==0x52494646){waveFormat=WaveJoiner.inspect(input,268435456L);rate=waveFormat.rate;channels=waveFormat.channels;wave=new RandomAccessFile(input,"r");wave.seek(waveFormat.offset);waveLeft=waveFormat.length;durationUs=waveLeft/waveFormat.align*1000000L/rate;return;}}
   extractor=new MediaExtractor();extractor.setDataSource(input.getPath());int track=-1;for(int n=0;n<extractor.getTrackCount();n++){String mime=extractor.getTrackFormat(n).getString(MediaFormat.KEY_MIME);if(mime!=null&&mime.startsWith("audio/")){track=n;break;}}if(track<0)throw new IOException("O fundo não contém áudio compatível.");extractor.selectTrack(track);MediaFormat format=extractor.getTrackFormat(track);if(format.containsKey(MediaFormat.KEY_DURATION))durationUs=format.getLong(MediaFormat.KEY_DURATION);format.setInteger(MediaFormat.KEY_PCM_ENCODING,AudioFormat.ENCODING_PCM_16BIT);codec=MediaCodec.createDecoderByType(format.getString(MediaFormat.KEY_MIME));codec.configure(format,null,null,0);codec.start();
  }catch(Exception e){close();throw e;}
 }
 static BackgroundPcm prepare(File input,File directory,BooleanSupplier cancel,Progress progress)throws Exception{return new BackgroundPcm(input,directory,cancel,progress);}
 static BackgroundPcm decode(File input,File directory,BooleanSupplier cancel)throws Exception{BackgroundPcm b=prepare(input,directory,cancel,null);try{b.ensure(Long.MAX_VALUE);return b;}finally{b.close();}}
 void check()throws IOException{if(cancel.getAsBoolean()||Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(closed&&!complete)throw new IOException("Preparação do fundo interrompida.");}
 void ensure(long requiredFrames)throws IOException{check();lastOutput=System.nanoTime();while(!complete&&(rate==0||frames<requiredFrames)){check();if(wave!=null)waveStep();else codecStep();if(!complete&&System.nanoTime()-lastOutput>30000000000L)throw new IOException("O fundo não respondeu. Escolha outro áudio ou retome sem fundo.");}if(frames<1)throw new IOException("O fundo está vazio.");}
 void append(byte[] bytes)throws IOException{if(rate<8000||rate>192000||channels<1||channels>8||bytes.length%(channels*2)!=0)throw new IOException("Formato de fundo inválido.");if(file.length()+bytes.length>1073741824L||directory.getUsableSpace()<bytes.length+33554432L)throw new IOException("Sem espaço para preparar este fundo. Escolha um áudio menor.");output.write(bytes);frames+=bytes.length/(channels*2);positionUs=frames*1000000L/rate;lastOutput=System.nanoTime();if(progress!=null&&(lastProgress==0||lastOutput-lastProgress>=500000000L)){lastProgress=lastOutput;progress.update(positionUs,durationUs);}}
 void finish()throws IOException{if(frames<1)throw new IOException("O fundo está vazio.");output.getFD().sync();output.close();output=null;try(FileOutputStream raw=new FileOutputStream(meta);DataOutputStream out=new DataOutputStream(raw)){out.writeInt(rate);out.writeInt(channels);out.flush();raw.getFD().sync();}complete=true;}
 void waveStep()throws IOException{if(waveLeft==0){finish();return;}int count=(int)Math.min(waveLeft,65536/waveFormat.align*waveFormat.align);byte[] input=new byte[count];wave.readFully(input);byte[] bytes;if(waveFormat.codec==1&&waveFormat.bits==16)bytes=input;else{bytes=new byte[count/(waveFormat.bits/8)*2];int at=0;for(int n=0;n<count;n+=waveFormat.bits/8){int sample=(int)Math.max(-32768,Math.min(32767,Math.round(BackgroundMixer.decode(input,n,waveFormat.codec,waveFormat.bits)*32768)));bytes[at++]=(byte)sample;bytes[at++]=(byte)(sample>>8);}}append(bytes);waveLeft-=count;if(waveLeft==0)finish();}
 void codecStep()throws IOException{
  try{boolean fed=false,drained=false;
   // Never wait for an input slot while decoded output is waiting to be drained.
   for(int n=0;n<8&&!inputDone;n++){int index=codec.dequeueInputBuffer(0);if(index<0)break;ByteBuffer buffer=codec.getInputBuffer(index);if(buffer==null)throw new IOException("Entrada de áudio indisponível.");buffer.clear();int count=extractor.readSampleData(buffer,0);if(count<0){codec.queueInputBuffer(index,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputDone=true;}else{codec.queueInputBuffer(index,0,count,Math.max(0,extractor.getSampleTime()),0);extractor.advance();}fed=true;}
   for(int n=0;n<16&&!complete;n++){MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();int index=codec.dequeueOutputBuffer(info,n==0&&!fed?10000:0);if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){MediaFormat f=codec.getOutputFormat();int r=f.getInteger(MediaFormat.KEY_SAMPLE_RATE),c=f.getInteger(MediaFormat.KEY_CHANNEL_COUNT);if(rate>0&&(rate!=r||channels!=c))throw new IOException("O formato do fundo mudou durante a leitura.");rate=r;channels=c;encoding=f.containsKey(MediaFormat.KEY_PCM_ENCODING)?f.getInteger(MediaFormat.KEY_PCM_ENCODING):AudioFormat.ENCODING_PCM_16BIT;if(rate<8000||rate>192000||channels<1||channels>8||encoding!=AudioFormat.ENCODING_PCM_16BIT&&encoding!=AudioFormat.ENCODING_PCM_FLOAT)throw new IOException("Formato de fundo não suportado.");drained=true;continue;}if(index<0)break;
    try{if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){if(rate==0)throw new IOException("Fundo sem formato PCM.");ByteBuffer buffer=codec.getOutputBuffer(index);if(buffer==null)throw new IOException("Saída de áudio indisponível.");buffer.position(info.offset);buffer.limit(info.offset+info.size);byte[] bytes;if(encoding==AudioFormat.ENCODING_PCM_FLOAT){buffer.order(ByteOrder.LITTLE_ENDIAN);bytes=new byte[buffer.remaining()/4*2];int at=0;while(buffer.remaining()>=4){float value=buffer.getFloat();int sample=Float.isNaN(value)?0:Math.max(-32768,Math.min(32767,Math.round(value*32767)));bytes[at++]=(byte)sample;bytes[at++]=(byte)(sample>>8);}}else{bytes=new byte[buffer.remaining()];buffer.get(bytes);}append(bytes);}outputDone=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;}finally{codec.releaseOutputBuffer(index,false);}drained=true;if(outputDone)finish();
   }
   if(!fed&&!drained)check();
  }catch(IllegalStateException|IllegalArgumentException e){throw new IOException("O aparelho não conseguiu descodificar este fundo.",e);}
 }
 void mix(File voice,File target,long firstFrame,int volume,WaveJoiner.Cancel cancelled)throws IOException{WaveJoiner.Format f=WaveJoiner.inspect(voice);if(rate==0)ensure(1);double end=(firstFrame+f.length/f.align)*(double)rate/f.rate;long needed=end>=Long.MAX_VALUE-2?Long.MAX_VALUE:(long)Math.ceil(end)+2;ensure(needed);BackgroundMixer.mix(voice,target,file,rate,channels,firstFrame,volume,cancelled,complete);}
 public void close(){closed=true;if(output!=null)try{output.close();}catch(IOException ignored){}output=null;if(wave!=null)try{wave.close();}catch(IOException ignored){}wave=null;if(extractor!=null){extractor.release();extractor=null;}if(codec!=null){try{codec.stop();}catch(Exception ignored){}try{codec.release();}catch(Exception ignored){}codec=null;}}
}
